#!/usr/bin/env python3
"""Encode manual review decisions, with source citations, for all 33 original skips."""
from pathlib import Path
import json,csv,re
ROOT=Path(__file__).resolve().parent;DECODED=ROOT/'results/differential/allsafe/apktool'
items=json.loads((ROOT.parent/'data/api-agent-verification.json').read_text())['report']['skipped']
# Deliberately authored labels, NOT generated by DiscoveryExclusion or its domain list.
reviews=[
('correct','XML namespace','SOAP envelope namespace inside the HardcodedCredentials request body; not a destination.'),
('correct','XML namespace','Namespace on SOAP credential elements, not an HTTP request destination.'),
('incorrect','actual external request','CertificatePinning constructs an OkHttp Request and enqueues GET /json. This is relevant app traffic. Keep as an external dependency requiring scoped testing; do not actively scan the shared service.'),
('correct','author profile','About screen opens the author Medium profile through a browser intent.'),
('correct','author profile','About screen opens the author GitHub profile through a browser intent.'),
('correct','author profile','About screen opens the author X profile through a browser intent.'),
('correct','metadata namespace','ExifInterface XMP namespace signature; not a network call.'),
('correct','license text','Apache URL inside bundled LICENSE.txt; not a backend.'),
('correct','documentation','Tink validation error points to KMS documentation; not a configured KMS key URI.'),
('correct','console help','Firebase connection error points operators to the Firebase console.'),
('correct','migration documentation','Firebase Kotlin deprecation annotation links migration instructions.'),
('correct','documentation','Firebase out-of-memory diagnostic links Android retrieval documentation.'),
('correct','documentation','Same SDK error diagnostic links iOS data-structure documentation.'),
('incorrect','SDK base requiring app binding','Firebase Storage NetworkRequest base is used by the SDK; app InsecureProviders invokes getReferenceFromUrl for gs://allsafe-8cef0.appspot.com/readme.txt, also backed by google_storage_bucket. Generic /v0 should not be probed itself, but discarding it loses an attributable storage endpoint requiring mapping/assessment.'),
('correct','SDK issue reporting','SDK errors link the Firebase GitHub repository for support.'),
('correct','generic service URI','Google Play Services generic Google+ URI constant; no application-specific resource or direct Allsafe request established.'),
('correct','test placeholder','AndroidX BrowserActionsIntent.TEST_URL; library example/test URL.'),
('correct','documentation','Firebase transaction warning links persistence documentation.'),
('correct','OAuth scope identifier','Google Scopes.APP_STATE capability identifier, not a fetch URL.'),
('correct','OAuth scope identifier','Google Scopes.CLOUD_SAVE capability identifier, not a fetch URL.'),
('correct','OAuth scope identifier','Google Scopes.DRIVE capability identifier, not a fetch URL.'),
('correct','OAuth scope identifier','Google Scopes.DRIVE_APPFOLDER capability identifier, not a fetch URL.'),
('correct','OAuth scope identifier','Google Scopes.DRIVE_APPS capability identifier, not a fetch URL.'),
('correct','OAuth scope identifier','Google Scopes.DRIVE_FILE capability identifier, not a fetch URL.'),
('correct','OAuth scope identifier','Google Scopes.GAMES capability identifier, not a fetch URL.'),
('correct','OAuth scope identifier','Google FirstPartyScopes.GAMES_1P capability identifier, not a fetch URL.'),
('correct','OAuth scope identifier','Google games_lite capability identifier passed to Scope, not a fetch URL.'),
('correct','OAuth scope identifier','Google Scopes.PLUS_LOGIN capability identifier, not a fetch URL.'),
('correct','OAuth scope identifier','Google Scopes.PLUS_ME capability identifier, not a fetch URL.'),
('correct','OAuth scope identifier','Google Scopes.LEGACY_USERINFO_EMAIL capability identifier, not a fetch URL.'),
('correct','OAuth scope identifier','Google Scopes.LEGACY_USERINFO_PROFILE capability identifier, not a fetch URL.'),
('correct','language issue reference','Kotlin reflection error links a compiler issue.'),
('correct','language issue reference','Kotlin deprecation annotation links a compiler issue.')]
assert len(items)==len(reviews)==33
sources={i:[] for i in range(33)}
for p in DECODED.rglob('*'):
 if not p.is_file() or p.suffix not in ['.smali','.xml','.txt']:continue
 for n,line in enumerate(p.read_text(errors='replace').splitlines(),1):
  for i,e in enumerate(items):
   if len(sources[i])<3 and e['url'] in line:sources[i].append(str(p.relative_to(ROOT))+':'+str(n))
rows=[]
for i,(e,(decision,category,rationale)) in enumerate(zip(items,reviews)):
 assert sources[i], e['url']
 rows.append(dict(index=i+1,endpoint_id=e['endpoint_id'],url=e['url'],original_skip_reason=e['observation'],coverage_disposition=decision,category=category,rationale=rationale,evidence=sources[i]))
rows[13]['evidence']+=['results/differential/allsafe/apktool/smali_classes4/infosecadventures/allsafe/challenges/InsecureProviders.smali:201','results/differential/allsafe/apktool/res/values/strings.xml:85']
(ROOT/'results/skip-audit.json').write_text(json.dumps(rows,indent=2)+'\n')
with open(ROOT/'results/skip-audit.csv','w') as f:
 w=csv.DictWriter(f,fieldnames=rows[0].keys());w.writeheader();w.writerows({**r,'evidence':'; '.join(r['evidence'])} for r in rows)
summary={'population':'35 records in the original Allsafe API agent run; two selected plus 33 skipped','reviewed_skips':33,'correct_coverage_skips':31,'incorrect_coverage_discards':2,'skip_decision_accuracy':31/33,'selection_true_positives':2,'selection_false_negatives':2,'selection_recall':2/4,'scope_eligible_selection_recall':2/3,'definition':'Recall = selected relevant records / all manually relevant records in this fixed inventory. Firebase root and REST route are separate original records, not independent backends. httpbin is app-used but shared third party; exclude it from the scope-eligible denominator. Storage needs concrete bucket/path resolution before a probe.','not_measured':'Full application API recall: constructed/non-HTTP/encrypted endpoints beyond this fixed inventory remain outside this denominator. No vulnerability scan was run against httpbin or the generic Storage root.'}
(ROOT/'results/skip-summary.json').write_text(json.dumps(summary,indent=2)+'\n');print(json.dumps(summary,indent=2))
